package com.bank.parquet.model;

import java.math.BigDecimal;
import java.time.LocalDate;

// A WIDE record — in reality dozens of columns; we model four.
public class Transaction {
    private final String txnId;
    private final String accountId;
    private final BigDecimal amount;
    private final LocalDate txnDate;

    public Transaction(String txnId, String accountId, BigDecimal amount, LocalDate txnDate) {
        this.txnId = txnId;
        this.accountId = accountId;
        this.amount = amount;
        this.txnDate = txnDate;
    }
    public String getTxnId() { return txnId; }
    public String getAccountId() { return accountId; }
    public BigDecimal getAmount() { return amount; }
    public LocalDate getTxnDate() { return txnDate; }
}
