package com.bank.parquet.store;

import com.bank.parquet.model.Transaction;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// ROW-oriented: every read of one column still touches ALL columns of each row.
public class RowStore {
    private static final Logger log = Logger.getLogger(RowStore.class.getName());
    private final List<Transaction> rows = new ArrayList<>();

    public void add(Transaction t) { rows.add(t); }

    public BigDecimal sumAmount() {
        long cellsRead = 0;
        BigDecimal total = BigDecimal.ZERO;
        for (Transaction t : rows) {
            cellsRead += 4;               // must read all 4 fields per row
            total = total.add(t.getAmount());
        }
        log.info("ROW store summed amount, cells read = " + cellsRead);
        return total;
    }
}
