package com.bank.parquet.store;

import com.bank.parquet.model.Transaction;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import java.util.logging.Logger;

// COLUMN-oriented (Parquet-like): columns stored separately + min/max stats per row group.
public class ColumnStore {
    private static final Logger log = Logger.getLogger(ColumnStore.class.getName());

    private final List<BigDecimal> amountCol = new ArrayList<>();
    private final List<LocalDate> dateCol = new ArrayList<>();
    private LocalDate minDate, maxDate;  // row-group statistics for pushdown

    public void add(Transaction t) {
        amountCol.add(t.getAmount());
        dateCol.add(t.getTxnDate());
        minDate = (minDate == null || t.getTxnDate().isBefore(minDate)) ? t.getTxnDate() : minDate;
        maxDate = (maxDate == null || t.getTxnDate().isAfter(maxDate)) ? t.getTxnDate() : maxDate;
    }

    // Column pruning: read ONLY the amount column.
    public BigDecimal sumAmount() {
        long cellsRead = amountCol.size(); // only 1 column touched
        BigDecimal total = BigDecimal.ZERO;
        for (BigDecimal a : amountCol) total = total.add(a);
        log.info("COLUMN store summed amount, cells read = " + cellsRead);
        return total;
    }

    // Predicate pushdown: skip the whole row group if the date cannot match.
    public BigDecimal sumAmountForDate(LocalDate target) {
        if (target.isBefore(minDate) || target.isAfter(maxDate)) {
            log.info(() -> "PUSHDOWN: skipped row group (target " + target
                    + " outside [" + minDate + "," + maxDate + "]) — 0 cells read");
            return BigDecimal.ZERO;
        }
        BigDecimal total = BigDecimal.ZERO;
        for (int i = 0; i < dateCol.size(); i++) {
            if (dateCol.get(i).equals(target)) total = total.add(amountCol.get(i));
        }
        log.info(() -> "Scanned row group for date " + target);
        return total;
    }
}
