package com.bank.parquet;

import com.bank.parquet.model.Transaction;
import com.bank.parquet.store.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.logging.Logger;

public class ParquetDemo {
    private static final Logger log = Logger.getLogger(ParquetDemo.class.getName());

    public static void main(String[] args) {
        LocalDate d = LocalDate.of(2024, 10, 29);
        List<Transaction> data = List.of(
            new Transaction("T1", "SAV2001", new BigDecimal("1200.00"), d),
            new Transaction("T2", "SAV2001", new BigDecimal("800.00"), d),
            new Transaction("T3", "CUR3001", new BigDecimal("5000.00"), d),
            new Transaction("T4", "CUR3001", new BigDecimal("2500.00"), d)
        );

        RowStore rowStore = new RowStore();
        ColumnStore colStore = new ColumnStore();
        data.forEach(t -> { rowStore.add(t); colStore.add(t); });

        log.info("=== SUM(amount) — same answer, very different I/O ===");
        log.info("Row total   = " + rowStore.sumAmount());
        log.info("Column total= " + colStore.sumAmount());

        log.info("=== Predicate pushdown for a non-matching date ===");
        log.info("Result = " + colStore.sumAmountForDate(LocalDate.of(2023, 1, 1)));
    }
}
